def get_alerts(state, **_extra):
    import json, os, datetime, time, random, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0428000" if __import__("os").path.isdir("./environment_mix/0428000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            s = v.strip()
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randrange(100000, 999999)}"

    def _as_int(x):
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        if isinstance(x, str) and x.strip().isdigit():
            try:
                return int(x.strip())
            except ValueError:
                return None
        return None

    def _select_api_key():
        # Ambient auth: pick any active key that can serve (has limits).
        keys = _load("api_keys.json")
        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            rpm = _as_int(k.get("requests_per_minute_limit"))
            rpd = _as_int(k.get("requests_per_day_limit"))
            if rpm is None or rpd is None:
                continue
            if not (1 <= rpm <= 6000 and 1 <= rpd <= 10000000):
                continue
            if isinstance(k.get("id"), str) and k["id"]:
                candidates.append(k)
        if not candidates:
            return None, keys
        # Prefer least recently used (or never used)
        def key_sort(k):
            lu = _parse_dt(k.get("last_used_at"))
            return (lu is not None, lu or _now())
        candidates.sort(key=key_sort)
        return candidates[0], keys

    def _rate_limited(api_key_row):
        reqs = _load("api_requests.json")
        now = _now()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_start = now.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

        key_id = api_key_row["id"]
        in_minute = 0
        in_day = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt >= minute_ago:
                in_minute += 1
            if dt >= day_start:
                in_day += 1

        rpm = _as_int(api_key_row.get("requests_per_minute_limit")) or 0
        rpd = _as_int(api_key_row.get("requests_per_day_limit")) or 0
        return (in_minute >= rpm) or (in_day >= rpd), {"minute_used": in_minute, "day_used": in_day, "rpm": rpm, "rpd": rpd}

    def _log_request(api_key_id, tool_name, state_val, lat_val, lon_val, cache_key, served_from_cache, http_status, err_code, err_msg, upstream_provider, upstream_url, upstream_status, latency_ms):
        reqs = _load("api_requests.json")
        now = _now()
        row = {
            "id": _gen_id("req"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "state": state_val,
            "latitude": lat_val,
            "longitude": lon_val,
            "cache_key": cache_key,
            "served_from_cache": bool(served_from_cache),
            "response_status_code": int(http_status),
            "error_code": err_code,
            "error_message": err_msg,
            "upstream_provider": upstream_provider,
            "upstream_request_url": upstream_url,
            "upstream_status_code": upstream_status,
            "latency_ms": int(latency_ms),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }

        # Enforce api_requests constraints minimally
        if tool_name == "get-alerts":
            row["latitude"] = None
            row["longitude"] = None
        if tool_name == "get-forecast":
            row["state"] = None

        reqs.append(row)
        _save("api_requests.json", reqs)
        return row

    def _count_alerts(raw_payload):
        if isinstance(raw_payload, dict):
            feats = raw_payload.get("features")
            if isinstance(feats, list):
                return len(feats)
            items = raw_payload.get("items")
            if isinstance(items, list):
                return len(items)
        if isinstance(raw_payload, list):
            return len(raw_payload)
        return 0

    def _find_fresh_snapshot(state_code):
        snaps = _load("alert_snapshots.json")
        now = _now()
        candidates = []
        for s in snaps:
            if not isinstance(s, dict):
                continue
            if s.get("state") != state_code:
                continue
            if s.get("status") != "fresh":
                continue
            exp = _parse_dt(s.get("expires_at"))
            if exp is None or exp <= now:
                continue
            fetched = _parse_dt(s.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            candidates.append((fetched, s))
        if not candidates:
            return None
        candidates.sort(key=lambda x: x[0], reverse=True)
        return candidates[0][1]

    def _mark_prior_stale(state_code):
        snaps = _load("alert_snapshots.json")
        now = _now()
        changed = False
        for s in snaps:
            if not isinstance(s, dict):
                continue
            if s.get("state") != state_code:
                continue
            if s.get("status") == "fresh":
                exp = _parse_dt(s.get("expires_at"))
                if exp is None or exp <= now:
                    # fresh -> stale is legal
                    s["status"] = "stale"
                    s["updated_at"] = _iso(now)
                    changed = True
        if changed:
            _save("alert_snapshots.json", snaps)

    def _upstream_fetch_alerts(state_code):
        # Offline "upstream": deterministic pseudo-payload.
        # Simulate occasional failure based on state hash.
        h = int(hashlib.sha256(state_code.encode("utf-8")).hexdigest(), 16)
        fail = (h % 29) == 0  # ~3.4% failure
        upstream_url = f"https://api.weather.gov/alerts/active?area={state_code}"
        provider = "NWS"
        if fail:
            return {"ok": False, "provider": provider, "url": upstream_url, "status": 503, "error": "Upstream unavailable"}
        # Create 0-4 alerts deterministically
        n = h % 5
        features = []
        now = _now()
        for i in range(n):
            features.append({
                "id": f"{state_code}-{(h >> (i*3)) & 0xffff:04x}",
                "type": "Feature",
                "properties": {
                    "areaDesc": state_code,
                    "headline": f"Weather Alert {i+1} for {state_code}",
                    "severity": ["Minor", "Moderate", "Severe", "Extreme"][((h >> (i*5)) % 4)],
                    "sent": _iso(now),
                }
            })
        payload = {"type": "FeatureCollection", "features": features}
        return {"ok": True, "provider": provider, "url": upstream_url, "status": 200, "json": payload}

    start = time.perf_counter()
    tool_name = "get-alerts"

    # Resolve ambient auth key
    api_key, api_keys_all = _select_api_key()
    if api_key is None:
        latency_ms = int((time.perf_counter() - start) * 1000)
        # Cannot log without an api_key_id that satisfies FK; return UNAUTHORIZED.
        return _err("UNAUTHORIZED", "No authorized API key available to serve this request.")

    # Validate key status (active required)
    if api_key.get("status") in ("suspended", "revoked"):
        latency_ms = int((time.perf_counter() - start) * 1000)
        _log_request(api_key["id"], tool_name, state, None, None, f"alerts:{state}", False, 403, "KEY_INACTIVE",
                     "API key is not active.", None, None, None, latency_ms)
        return _err("UNAUTHORIZED", "API key inactive.", http_status=403)

    # Validate input
    valid_state = isinstance(state, str) and len(state) == 2 and re.fullmatch(r"[A-Z]{2}", state or "") is not None
    cache_key = f"alerts:{state}" if isinstance(state, str) else "alerts:"

    if not valid_state:
        latency_ms = int((time.perf_counter() - start) * 1000)
        _log_request(api_key["id"], tool_name, state if isinstance(state, str) else None, None, None, cache_key, False, 400,
                     "VALIDATION_ERROR", "state must be exactly 2 uppercase letters A-Z.", None, None, None, latency_ms)
        return _err("VALIDATION_ERROR", "state must be exactly 2 uppercase letters A-Z.")

    # Rate limit / quota enforcement (sliding minute + UTC day), rejected calls are logged.
    limited, usage = _rate_limited(api_key)
    if limited:
        latency_ms = int((time.perf_counter() - start) * 1000)
        _log_request(api_key["id"], tool_name, state, None, None, cache_key, False, 429, "RATE_LIMITED",
                     "Rate limit or daily quota exceeded.", None, None, None, latency_ms)
        return _err("RATE_LIMIT", "Rate limit exceeded.", http_status=429, details=usage)

    # Serve from cache if fresh
    fresh = _find_fresh_snapshot(state)
    if fresh is not None:
        # Update key last_used_at
        now = _now()
        for k in api_keys_all:
            if isinstance(k, dict) and k.get("id") == api_key["id"]:
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                break
        _save("api_keys.json", api_keys_all)

        latency_ms = int((time.perf_counter() - start) * 1000)
        _log_request(api_key["id"], tool_name, state, None, None, cache_key, True, 200, None, None,
                     fresh.get("upstream_provider"), None, 200, latency_ms)
        return {
            "state": state,
            "cache_key": cache_key,
            "served_from_cache": True,
            "snapshot": fresh
        }

    # Cache miss/stale: mark expired fresh snapshots stale, then attempt upstream refresh
    _mark_prior_stale(state)
    upstream = _upstream_fetch_alerts(state)
    now = _now()
    ttl = datetime.timedelta(minutes=5)  # service TTL policy

    if not upstream.get("ok"):
        # Record an error snapshot
        snaps = _load("alert_snapshots.json")
        err_snap = {
            "id": _gen_id("asnap"),
            "state": state,
            "status": "error",
            "fetched_at": _iso(now),
            "expires_at": _iso(now + datetime.timedelta(minutes=1)),
            "upstream_provider": upstream.get("provider") or "NWS",
            "upstream_etag": None,
            "upstream_last_modified": None,
            "alert_count": 0,
            "raw_payload": {"error": upstream.get("error"), "provider_status": upstream.get("status")},
            "error_message": upstream.get("error") or "Upstream error",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        snaps.append(err_snap)
        _save("alert_snapshots.json", snaps)

        latency_ms = int((time.perf_counter() - start) * 1000)
        _log_request(api_key["id"], tool_name, state, None, None, cache_key, False, 502, "UPSTREAM_ERROR",
                     err_snap["error_message"], err_snap["upstream_provider"], upstream.get("url"), upstream.get("status"),
                     latency_ms)
        return _err("CONFLICT", "Upstream provider error.", http_status=502)

    payload = upstream.get("json")
    alert_count = _count_alerts(payload)

    # Insert fresh snapshot
    snaps = _load("alert_snapshots.json")
    new_snap = {
        "id": _gen_id("asnap"),
        "state": state,
        "status": "fresh",
        "fetched_at": _iso(now),
        "expires_at": _iso(now + ttl),
        "upstream_provider": upstream.get("provider") or "NWS",
        "upstream_etag": None,
        "upstream_last_modified": None,
        "alert_count": int(alert_count),
        "raw_payload": payload if payload is not None else {},
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    snaps.append(new_snap)
    _save("alert_snapshots.json", snaps)

    # Update key last_used_at
    for k in api_keys_all:
        if isinstance(k, dict) and k.get("id") == api_key["id"]:
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break
    _save("api_keys.json", api_keys_all)

    latency_ms = int((time.perf_counter() - start) * 1000)
    _log_request(api_key["id"], tool_name, state, None, None, cache_key, False, 200, None, None,
                 new_snap.get("upstream_provider"), upstream.get("url"), upstream.get("status"), latency_ms)

    return {
        "state": state,
        "cache_key": cache_key,
        "served_from_cache": False,
        "snapshot": new_snap
    }

def get_forecast(latitude, longitude, **_extra):
    import json, os, datetime, time, random, hashlib, math

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0428000" if __import__("os").path.isdir("./environment_mix/0428000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
