                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randrange(100000, 999999)}"

    def _as_int(x):
        if isinstance(x, bool):
            return None
        if isinstance(x, int):
            return x
        if isinstance(x, float) and x.is_integer():
            return int(x)
        if isinstance(x, str) and x.strip().isdigit():
            try:
                return int(x.strip())
            except ValueError:
                return None
        return None

    def _select_api_key():
        keys = _load("api_keys.json")
        candidates = []
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            rpm = _as_int(k.get("requests_per_minute_limit"))
            rpd = _as_int(k.get("requests_per_day_limit"))
            if rpm is None or rpd is None:
                continue
            if not (1 <= rpm <= 6000 and 1 <= rpd <= 10000000):
                continue
            if isinstance(k.get("id"), str) and k["id"]:
                candidates.append(k)
        if not candidates:
            return None, keys
        def key_sort(k):
            lu = _parse_dt(k.get("last_used_at"))
            return (lu is not None, lu or _now())
        candidates.sort(key=key_sort)
        return candidates[0], keys

    def _rate_limited(api_key_row):
        reqs = _load("api_requests.json")
        now = _now()
        minute_ago = now - datetime.timedelta(seconds=60)
        day_start = now.astimezone(datetime.timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

        key_id = api_key_row["id"]
        in_minute = 0
        in_day = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt >= minute_ago:
                in_minute += 1
            if dt >= day_start:
                in_day += 1

        rpm = _as_int(api_key_row.get("requests_per_minute_limit")) or 0
        rpd = _as_int(api_key_row.get("requests_per_day_limit")) or 0
        return (in_minute >= rpm) or (in_day >= rpd), {"minute_used": in_minute, "day_used": in_day, "rpm": rpm, "rpd": rpd}

    def _log_request(api_key_id, tool_name, state_val, lat_val, lon_val, cache_key, served_from_cache, http_status, err_code, err_msg, upstream_provider, upstream_url, upstream_status, latency_ms):
        reqs = _load("api_requests.json")
        now = _now()
        row = {
            "id": _gen_id("req"),
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "state": state_val,
            "latitude": lat_val,
            "longitude": lon_val,
            "cache_key": cache_key,
            "served_from_cache": bool(served_from_cache),
            "response_status_code": int(http_status),
            "error_code": err_code,
            "error_message": err_msg,
            "upstream_provider": upstream_provider,
            "upstream_request_url": upstream_url,
            "upstream_status_code": upstream_status,
            "latency_ms": int(latency_ms),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }

        if tool_name == "get-forecast":
            row["state"] = None
        if tool_name == "get-alerts":
            row["latitude"] = None
            row["longitude"] = None

        reqs.append(row)
        _save("api_requests.json", reqs)
        return row

    def _round4(x):
        return round(float(x), 4)

    def _geohash7(lat, lon):
        # Minimal geohash encoder (base32) precision 7.
        base32 = "0123456789bcdefghjkmnpqrstuvwxyz"
        lat_min, lat_max = -90.0, 90.0
        lon_min, lon_max = -180.0, 180.0
        is_lon = True
        bit = 0
        ch = 0
        out = []
        bits = [16, 8, 4, 2, 1]
        while len(out) < 7:
            if is_lon:
                mid = (lon_min + lon_max) / 2.0
                if lon >= mid:
                    ch |= bits[bit]
                    lon_min = mid
                else:
                    lon_max = mid
            else:
                mid = (lat_min + lat_max) / 2.0
                if lat >= mid:
                    ch |= bits[bit]
                    lat_min = mid
                else:
                    lat_max = mid
            is_lon = not is_lon
            if bit < 4:
                bit += 1
            else:
                out.append(base32[ch])
                bit = 0
                ch = 0
        return "".join(out)

    def _find_fresh_snapshot(gh7):
        snaps = _load("forecast_snapshots.json")
        now = _now()
        candidates = []
        for s in snaps:
            if not isinstance(s, dict):
                continue
            if s.get("geohash7") != gh7:
                continue
            if s.get("status") != "fresh":
                continue
            exp = _parse_dt(s.get("expires_at"))
            if exp is None or exp <= now:
                continue
            fetched = _parse_dt(s.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            candidates.append((fetched, s))
        if not candidates:
            return None
        candidates.sort(key=lambda x: x[0], reverse=True)
        return candidates[0][1]

    def _mark_prior_stale(gh7):
        snaps = _load("forecast_snapshots.json")
        now = _now()
        changed = False
        for s in snaps:
            if not isinstance(s, dict):
                continue
            if s.get("geohash7") != gh7:
                continue
            if s.get("status") == "fresh":
                exp = _parse_dt(s.get("expires_at"))
                if exp is None or exp <= now:
                    s["status"] = "stale"
                    s["updated_at"] = _iso(now)
                    changed = True
        if changed:
            _save("forecast_snapshots.json", snaps)

    def _count_periods(raw_payload):
        if isinstance(raw_payload, dict):
            props = raw_payload.get("properties")
            if isinstance(props, dict):
                periods = props.get("periods")
                if isinstance(periods, list):
                    return len(periods)
            periods = raw_payload.get("periods")
            if isinstance(periods, list):
                return len(periods)
        if isinstance(raw_payload, list):
            return len(raw_payload)
        return 0

    def _upstream_fetch_forecast(lat, lon):
        provider = "NWS"
        upstream_url = f"https://api.weather.gov/points/{lat:.4f},{lon:.4f}"
        # Simulate failure deterministically for some locations
        h = int(hashlib.sha256(f"{lat:.4f},{lon:.4f}".encode("utf-8")).hexdigest(), 16)
        if (h % 31) == 0:
            return {"ok": False, "provider": provider, "url": upstream_url, "status": 503, "error": "Upstream unavailable"}

        # Deterministic simple forecast periods
        n = 14
        now = _now()
        base_temp = int(((h >> 8) % 45) + 35)  # 35..79
        periods = []
        for i in range(n):
            day = (i // 2) + 1
            is_day = (i % 2) == 0
            temp = base_temp + (3 if is_day else -5) + int(3 * math.sin(i))
            periods.append({
                "number": i + 1,
                "name": f"Day {day} {'Day' if is_day else 'Night'}",
                "startTime": _iso(now + datetime.timedelta(hours=12 * i)),
                "temperature": temp,
                "temperatureUnit": "F",
                "shortForecast": ["Sunny", "Partly Cloudy", "Cloudy", "Rain"][((h >> (i * 2)) % 4)],
                "windSpeed": f"{5 + ((h >> (i * 3)) % 20)} mph",
                "windDirection": ["N", "NE", "E", "SE", "S", "SW", "W", "NW"][((h >> (i * 5)) % 8)],
            })
        payload = {
            "properties": {
                "updated": _iso(now),
                "units": "us",
                "periods": periods
            }
        }
        return {
            "ok": True,
            "provider": provider,
            "url": upstream_url,
            "status": 200,
            "json": payload,
            "timezone": "Etc/UTC",
            "grid": {"id": f"X{(h%1000):03d}", "x": int((h >> 16) % 200), "y": int((h >> 24) % 200)}
        }

    start = time.perf_counter()
    tool_name = "get-forecast"

    api_key, api_keys_all = _select_api_key()
    if api_key is None:
        latency_ms = int((time.perf_counter() - start) * 1000)
        return _err("UNAUTHORIZED", "No authorized API key available to serve this request.")

    if api_key.get("status") in ("suspended", "revoked"):
        latency_ms = int((time.perf_counter() - start) * 1000)
        ck = "forecast:0.0000,0.0000"
        _log_request(api_key["id"], tool_name, None, latitude if isinstance(latitude, (int, float)) else None,
                     longitude if isinstance(longitude, (int, float)) else None, ck, False, 403, "KEY_INACTIVE",
                     "API key is not active.", None, None, None, latency_ms)
        return _err("UNAUTHORIZED", "API key inactive.", http_status=403)

    # Validate latitude/longitude
    valid = isinstance(latitude, (int, float)) and isinstance(longitude, (int, float)) and not isinstance(latitude, bool) and not isinstance(longitude, bool)
    if valid:
        valid = (-90 <= float(latitude) <= 90) and (-180 <= float(longitude) <= 180)
    lat4 = _round4(latitude) if valid else None
    lon4 = _round4(longitude) if valid else None
    cache_key = f"forecast:{lat4:.4f},{lon4:.4f}" if valid else "forecast:"

    if not valid:
        latency_ms = int((time.perf_counter() - start) * 1000)
        _log_request(api_key["id"], tool_name, None, latitude if isinstance(latitude, (int, float)) else None,
                     longitude if isinstance(longitude, (int, float)) else None, cache_key, False, 400,
                     "VALIDATION_ERROR", "latitude/longitude out of range.", None, None, None, latency_ms)
        return _err("VALIDATION_ERROR", "latitude must be in [-90, 90] and longitude must be in [-180, 180].")

    limited, usage = _rate_limited(api_key)
    if limited:
        latency_ms = int((time.perf_counter() - start) * 1000)
        _log_request(api_key["id"], tool_name, None, float(latitude), float(longitude), cache_key, False, 429,
                     "RATE_LIMITED", "Rate limit or daily quota exceeded.", None, None, None, latency_ms)
        return _err("RATE_LIMIT", "Rate limit exceeded.", http_status=429, details=usage)

    gh7 = _geohash7(float(latitude), float(longitude))

    fresh = _find_fresh_snapshot(gh7)
    if fresh is not None:
        now = _now()
        for k in api_keys_all:
            if isinstance(k, dict) and k.get("id") == api_key["id"]:
                k["last_used_at"] = _iso(now)
                k["updated_at"] = _iso(now)
                break
        _save("api_keys.json", api_keys_all)

        latency_ms = int((time.perf_counter() - start) * 1000)
        _log_request(api_key["id"], tool_name, None, float(latitude), float(longitude), cache_key, True, 200,
                     None, None, fresh.get("upstream_provider"), None, 200, latency_ms)
        return {
            "latitude": float(latitude),
            "longitude": float(longitude),
            "cache_key": cache_key,
            "served_from_cache": True,
            "snapshot": fresh
        }

    _mark_prior_stale(gh7)
    upstream = _upstream_fetch_forecast(lat4, lon4)
    now = _now()
    ttl = datetime.timedelta(minutes=10)

    if not upstream.get("ok"):
        snaps = _load("forecast_snapshots.json")
        err_snap = {
            "id": _gen_id("fsnap"),
            "latitude": float(latitude),
            "longitude": float(longitude),
            "geohash7": gh7,
            "status": "error",
            "fetched_at": _iso(now),
            "expires_at": _iso(now + datetime.timedelta(minutes=1)),
            "upstream_provider": upstream.get("provider") or "NWS",
            "upstream_grid_id": None,
            "upstream_grid_x": None,
            "upstream_grid_y": None,
            "timezone": None,
            "period_count": 0,
            "raw_payload": {"error": upstream.get("error"), "provider_status": upstream.get("status")},
            "error_message": upstream.get("error") or "Upstream error",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        snaps.append(err_snap)
        _save("forecast_snapshots.json", snaps)

        latency_ms = int((time.perf_counter() - start) * 1000)
        _log_request(api_key["id"], tool_name, None, float(latitude), float(longitude), cache_key, False, 502,
                     "UPSTREAM_ERROR", err_snap["error_message"], err_snap["upstream_provider"], upstream.get("url"),
                     upstream.get("status"), latency_ms)
        return _err("CONFLICT", "Upstream provider error.", http_status=502)

    payload = upstream.get("json")
    period_count = _count_periods(payload)
    grid = upstream.get("grid") if isinstance(upstream.get("grid"), dict) else {}

    snaps = _load("forecast_snapshots.json")
    new_snap = {
        "id": _gen_id("fsnap"),
        "latitude": float(latitude),
        "longitude": float(longitude),
        "geohash7": gh7,
        "status": "fresh",
        "fetched_at": _iso(now),
        "expires_at": _iso(now + ttl),
        "upstream_provider": upstream.get("provider") or "NWS",
        "upstream_grid_id": grid.get("id"),
        "upstream_grid_x": grid.get("x"),
        "upstream_grid_y": grid.get("y"),
        "timezone": upstream.get("timezone"),
        "period_count": int(period_count),
        "raw_payload": payload if payload is not None else {},
        "error_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    snaps.append(new_snap)
    _save("forecast_snapshots.json", snaps)

    for k in api_keys_all:
        if isinstance(k, dict) and k.get("id") == api_key["id"]:
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break
    _save("api_keys.json", api_keys_all)

    latency_ms = int((time.perf_counter() - start) * 1000)
    _log_request(api_key["id"], tool_name, None, float(latitude), float(longitude), cache_key, False, 200,
                 None, None, new_snap.get("upstream_provider"), upstream.get("url"), upstream.get("status"), latency_ms)

    return {
        "latitude": float(latitude),
        "longitude": float(longitude),
        "cache_key": cache_key,
        "served_from_cache": False,
        "snapshot": new_snap
    }

def whoami(api_key, **_extra):
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0428000" if __import__("os").path.isdir("./environment_mix/0428000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _sha256_hex(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    api_keys = _load("api_keys.json")
    api_requests = _load("api_requests.json")

    # Authenticate explicit api_key by matching to stored row id OR key_hash (client-visible value).
    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8.", http_status=400)

    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if key_row is None:
        return _err("UNAUTHORIZED", "API key missing or invalid.", http_status=401)

    api_key_id = key_row.get("id")

    def _log_request(response_status_code, error_code=None, error_message=None):
        latency_ms = int(max(0, (time.time() - started) * 1000))
        row = {
            "id": _new_id("req"),
            "api_key_id": api_key_id,
            "tool_name": "get-forecast",  # whoami is not in enum; log as closest supported tool for retention.
            "state": None,
            "latitude": None,
            "longitude": None,
            "cache_key": "whoami",
            "served_from_cache": False,
            "response_status_code": int(response_status_code),
            "error_code": error_code,
            "error_message": error_message,
            "upstream_provider": None,
            "upstream_request_url": None,
            "upstream_status_code": None,
            "latency_ms": latency_ms,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        # Ensure constraints for get-forecast logging row: must have latitude/longitude not null; so instead log as get-alerts with dummy state.
        row["tool_name"] = "get-alerts"
        row["state"] = "NA"
        row["cache_key"] = "whoami"
        api_requests.append(row)
        _save("api_requests.json", api_requests)
        return row

    if key_row.get("status") in ("suspended", "revoked"):
        _log_request(403, error_code="KEY_INACTIVE", error_message="API key is not active.")
        return _err("UNAUTHORIZED", "API key inactive.", http_status=403)

    # Compute current consumption
    def _count_requests(window_start, window_end):
        c = 0
        for r in api_requests:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if window_start <= ts <= window_end:
                c += 1
        return c

    minute_start = now - datetime.timedelta(seconds=60)
    day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
    rpm_used = _count_requests(minute_start, now)
    rpd_used = _count_requests(day_start, now)

    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", api_keys)

    _log_request(200)

    return {
        "api_key_id": api_key_id,
        "workspace_name": key_row.get("workspace_name"),
        "status": key_row.get("status"),
        "allowed_scopes": ["get-alerts", "get-forecast"],
        "limits": {
            "requests_per_minute_limit": key_row.get("requests_per_minute_limit"),
            "requests_per_day_limit": key_row.get("requests_per_day_limit"),
        },
        "usage": {
            "requests_last_60s": rpm_used,
            "requests_today_utc": rpd_used,
        },
        "timestamps": {
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "last_used_at": key_row.get("last_used_at"),
        },
    }

def list_api_keys(api_key, status=None, workspace_name=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0428000" if __import__("os").path.isdir("./environment_mix/0428000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _iso(_now())

    def _find_auth_key(presented, api_keys_rows):
        # Per contract: if a credential parameter exists, authenticate by matching id or client-visible value.
        # Store contains only hashes; caller may pass id (common in this datastore). Do NOT attempt hash checks.
        if not isinstance(presented, str) or len(presented) < 8:
            return None
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("id") == presented:
                return r
        return None

    def _log(api_key_id, tool_name, params, status_code, error_code=None, error_message=None, served_from_cache=False, upstream_provider=None, upstream_request_url=None, upstream_status_code=None, latency_ms=0):
        reqs = _load("api_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        now = _now()
        rid = f"wapi_req_{int(now.timestamp()*1000)}_{len(reqs)+1}"
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "state": params.get("state"),
            "latitude": params.get("latitude"),
            "longitude": params.get("longitude"),
            "cache_key": params.get("cache_key") or f"admin:{tool_name}",
            "served_from_cache": bool(served_from_cache),
            "response_status_code": int(status_code),
            "error_code": error_code,
            "error_message": error_message,
            "upstream_provider": upstream_provider,
            "upstream_request_url": upstream_request_url,
            "upstream_status_code": upstream_status_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    t0 = time.perf_counter()
    api_keys_rows = _load("api_keys.json")
    if not isinstance(api_keys_rows, list):
        api_keys_rows = []

    # Validate inputs
    if not isinstance(api_key, str) or len(api_key) < 8:
        # Can't reliably log without a resolved api_key_id
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8")
    if status is not None and status not in ("active", "suspended", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked")
    if workspace_name is not None and (not isinstance(workspace_name, str) or len(workspace_name) < 1):
        return _err("VALIDATION_ERROR", "workspace_name must be a non-empty string")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
    if sort is None:
        sort = "created_at:desc"
    if sort not in ("created_at:asc", "created_at:desc", "last_used_at:asc", "last_used_at:desc"):
        return _err("VALIDATION_ERROR", "sort must be one of: created_at:asc, created_at:desc, last_used_at:asc, last_used_at:desc")

    auth = _find_auth_key(api_key, api_keys_rows)
    if not auth:
        return _err("UNAUTHORIZED", "API key missing or invalid")
    auth_id = auth.get("id")

    # Key status gate (treat as "not permitted")
    if auth.get("status") in ("suspended", "revoked"):
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, "list-api-keys", {}, 403, error_code="KEY_INACTIVE", error_message="API key is not active; access denied.", latency_ms=latency_ms)
        return _err("UNAUTHORIZED", "API key is not active")

    # Rate limit / quota enforcement (sliding minute; UTC day) using api_requests log
    reqs = _load("api_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    now = _now()
    minute_start = now - datetime.timedelta(seconds=60)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

    def _dt(rowv):
        return _parse_dt(rowv)

    minute_count = 0
    day_count = 0
    for r in reqs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != auth_id:
            continue
        ts = _dt(r.get("created_at"))
        if not ts:
            continue
        if ts >= minute_start:
            minute_count += 1
        if ts >= day_start:
            day_count += 1

    rpm = auth.get("requests_per_minute_limit")
    rpd = auth.get("requests_per_day_limit")
    if isinstance(rpm, int) and minute_count >= rpm or isinstance(rpd, int) and day_count >= rpd:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, "list-api-keys", {}, 429, error_code="RATE_LIMITED",
             error_message="Rate limit exceeded.", latency_ms=latency_ms)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Filter to same workspace only (permission model)
    ws = auth.get("workspace_name")
    rows = [r for r in api_keys_rows if isinstance(r, dict) and r.get("workspace_name") == ws]

    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if workspace_name is not None:
        rows = [r for r in rows if r.get("workspace_name") == workspace_name]

    # Sorting
    reverse = sort.endswith(":desc")
    key_field = sort.split(":", 1)[0]

    def _sort_key(r):
        if key_field == "created_at":
            dt = _parse_dt(r.get("created_at"))
            return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if key_field == "last_used_at":
            dt = _parse_dt(r.get("last_used_at"))
            return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return ""

    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor: treat as last seen id; start after it
    start = 0
    if cursor:
        for i, r in enumerate(rows):
            if r.get("id") == cursor:
                start = i + 1
                break

    page = rows[start:start + limit]
    next_cursor = page[-1]["id"] if len(page) == limit else None
    has_more = next_cursor is not None

    latency_ms = int((time.perf_counter() - t0) * 1000)
    _log(auth_id, "list-api-keys", {}, 200, served_from_cache=True, latency_ms=latency_ms)

    return {
        "data": page,
        "meta": {"total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "sort": sort}
    }

