        if not isinstance(r, dict) or r.get("api_key_id") != auth_id:
            continue
        ts = _parse_dt(r.get("created_at"))
        if not ts:
            continue
        if ts >= minute_start:
            minute_count += 1
        if ts >= day_start:
            day_count += 1

    rpm = auth.get("requests_per_minute_limit")
    rpd = auth.get("requests_per_day_limit")
    if isinstance(rpm, int) and minute_count >= rpm or isinstance(rpd, int) and day_count >= rpd:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, "create-api-key", {}, 429, error_code="RATE_LIMITED", error_message="Rate limit exceeded.", latency_ms=latency_ms)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Permission model: only allow creating keys within caller's workspace
    if auth.get("workspace_name") != workspace_name:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, "create-api-key", {}, 403, error_code="FORBIDDEN", error_message="Not permitted to create keys for this workspace.", latency_ms=latency_ms)
        return _err("UNAUTHORIZED", "Not permitted")

    # Generate key material once; store only hash
    plaintext = "wkey_" + secrets.token_urlsafe(24)
    key_hash = "sha256:" + hashlib.sha256(plaintext.encode("utf-8")).hexdigest()

    # Uniqueness constraint: unique(key_hash)
    for r in api_keys_rows:
        if isinstance(r, dict) and r.get("key_hash") == key_hash:
            # Extremely unlikely; regenerate once
            plaintext = "wkey_" + secrets.token_urlsafe(24)
            key_hash = "sha256:" + hashlib.sha256(plaintext.encode("utf-8")).hexdigest()
            break
    for r in api_keys_rows:
        if isinstance(r, dict) and r.get("key_hash") == key_hash:
            latency_ms = int((time.perf_counter() - t0) * 1000)
            _log(auth_id, "create-api-key", {}, 409, error_code="CONFLICT", error_message="Generated key collided; retry.", latency_ms=latency_ms)
            return _err("CONFLICT", "Key collision; retry")

    new_id = f"wapi_key_{int(now.timestamp()*1000)}_{secrets.token_hex(6)}"
    created = {
        "id": new_id,
        "workspace_name": workspace_name,
        "key_hash": key_hash,
        "status": status,
        "requests_per_minute_limit": requests_per_minute_limit,
        "requests_per_day_limit": requests_per_day_limit,
        "created_at": _iso(now),
        "updated_at": _iso(now),
        "last_used_at": None
    }
    api_keys_rows.append(created)
    _save("api_keys.json", api_keys_rows)

    latency_ms = int((time.perf_counter() - t0) * 1000)
    _log(auth_id, "create-api-key", {}, 201, served_from_cache=False, latency_ms=latency_ms)

    return {"data": created, "plaintext_api_key": plaintext}

def update_api_key(api_key, id, workspace_name=None, requests_per_minute_limit=None, requests_per_day_limit=None, status=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0428000" if __import__("os").path.isdir("./environment_mix/0428000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _iso(_now())

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except ValueError:
            return None

    def _find_auth_key(presented, api_keys_rows):
        if not isinstance(presented, str) or len(presented) < 8:
            return None
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("id") == presented:
                return r
        return None

    def _log(api_key_id, tool_name, params, status_code, error_code=None, error_message=None, served_from_cache=False, upstream_provider=None, upstream_request_url=None, upstream_status_code=None, latency_ms=0):
        reqs = _load("api_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        now = _now()
        rid = f"wapi_req_{int(now.timestamp()*1000)}_{len(reqs)+1}"
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "state": params.get("state"),
            "latitude": params.get("latitude"),
            "longitude": params.get("longitude"),
            "cache_key": params.get("cache_key") or f"admin:{tool_name}",
            "served_from_cache": bool(served_from_cache),
            "response_status_code": int(status_code),
            "error_code": error_code,
            "error_message": error_message,
            "upstream_provider": upstream_provider,
            "upstream_request_url": upstream_request_url,
            "upstream_status_code": upstream_status_code,
            "latency_ms": int(latency_ms),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    t0 = time.perf_counter()
    api_keys_rows = _load("api_keys.json")
    if not isinstance(api_keys_rows, list):
        api_keys_rows = []

    # Validate required params
    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8")
    if not isinstance(id, str) or len(id) < 1:
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    # Validate optional params
    if workspace_name is not None and (not isinstance(workspace_name, str) or len(workspace_name) < 1):
        return _err("VALIDATION_ERROR", "workspace_name must be a non-empty string")
    if requests_per_minute_limit is not None:
        if not isinstance(requests_per_minute_limit, int):
            return _err("VALIDATION_ERROR", "requests_per_minute_limit must be an integer")
        if requests_per_minute_limit < 1 or requests_per_minute_limit > 6000:
            return _err("VALIDATION_ERROR", "requests_per_minute_limit must be between 1 and 6000")
    if requests_per_day_limit is not None:
        if not isinstance(requests_per_day_limit, int):
            return _err("VALIDATION_ERROR", "requests_per_day_limit must be an integer")
        if requests_per_day_limit < 1 or requests_per_day_limit > 10000000:
            return _err("VALIDATION_ERROR", "requests_per_day_limit must be between 1 and 10000000")
    if status is not None and status not in ("active", "suspended", "revoked"):
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked")

    auth = _find_auth_key(api_key, api_keys_rows)
    if not auth:
        return _err("UNAUTHORIZED", "API key missing or invalid")
    auth_id = auth.get("id")

    if auth.get("status") in ("suspended", "revoked"):
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, "update-api-key", {}, 403, error_code="KEY_INACTIVE", error_message="API key is not active; access denied.", latency_ms=latency_ms)
        return _err("UNAUTHORIZED", "API key is not active")

    # Rate limit / quota enforcement
    reqs = _load("api_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    now = _now()
    minute_start = now - datetime.timedelta(seconds=60)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

    minute_count = 0
    day_count = 0
    for r in reqs:
        if not isinstance(r, dict) or r.get("api_key_id") != auth_id:
            continue
        ts = _parse_dt(r.get("created_at"))
        if not ts:
            continue
        if ts >= minute_start:
            minute_count += 1
        if ts >= day_start:
            day_count += 1
    rpm = auth.get("requests_per_minute_limit")
    rpd = auth.get("requests_per_day_limit")
    if isinstance(rpm, int) and minute_count >= rpm or isinstance(rpd, int) and day_count >= rpd:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, "update-api-key", {}, 429, error_code="RATE_LIMITED", error_message="Rate limit exceeded.", latency_ms=latency_ms)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Locate target
    target = None
    for r in api_keys_rows:
        if isinstance(r, dict) and r.get("id") == id:
            target = r
            break
    if not target:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, "update-api-key", {}, 404, error_code="NOT_FOUND", error_message="API key id not found.", latency_ms=latency_ms)
        return _err("NOT_FOUND", "API key not found")

    # Permission: only within caller workspace
    if target.get("workspace_name") != auth.get("workspace_name"):
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, "update-api-key", {}, 403, error_code="FORBIDDEN", error_message="Not permitted to update keys outside your workspace.", latency_ms=latency_ms)
        return _err("UNAUTHORIZED", "Not permitted")

    # Must have an actual change
    if workspace_name is None and requests_per_minute_limit is None and requests_per_day_limit is None and status is None:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, "update-api-key", {}, 400, error_code="VALIDATION_ERROR", error_message="No fields to update.", latency_ms=latency_ms)
        return _err("VALIDATION_ERROR", "No fields to update")

    # Lifecycle transitions
    if status is not None:
        cur = target.get("status")
        allowed = {
            "active": ("suspended", "revoked"),
            "suspended": ("active", "revoked"),
            "revoked": ()
        }
        if cur not in allowed:
            latency_ms = int((time.perf_counter() - t0) * 1000)
            _log(auth_id, "update-api-key", {}, 409, error_code="INVALID_TRANSITION", error_message="Unknown current status.", latency_ms=latency_ms)
            return _err("INVALID_TRANSITION", "Unknown current status")
        if status != cur and status not in allowed[cur]:
            latency_ms = int((time.perf_counter() - t0) * 1000)
            _log(auth_id, "update-api-key", {}, 409, error_code="INVALID_TRANSITION", error_message=f"Invalid transition: {cur} -> {status}", latency_ms=latency_ms)
            return _err("INVALID_TRANSITION", f"Invalid transition: {cur} -> {status}")

    # Apply updates
    if workspace_name is not None:
        target["workspace_name"] = workspace_name
    if requests_per_minute_limit is not None:
        target["requests_per_minute_limit"] = requests_per_minute_limit
    if requests_per_day_limit is not None:
        target["requests_per_day_limit"] = requests_per_day_limit
    if status is not None:
        target["status"] = status
    target["updated_at"] = _iso(now)

    _save("api_keys.json", api_keys_rows)

    latency_ms = int((time.perf_counter() - t0) * 1000)
    _log(auth_id, "update-api-key", {}, 200, served_from_cache=False, latency_ms=latency_ms)

    return {"data": target}

def list_api_requests(api_key, tool_name=None, api_key_id=None, state=None, latitude=None, longitude=None, served_from_cache=None, response_status_code=None, created_at_gte=None, created_at_lte=None, limit=None, cursor=None, sort=None, **_extra):
