            return None
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("id") == presented:
                return r
        return None

    def _log(api_key_id_resolved, status_code, error_code=None, error_message=None, latency_ms=0):
        reqs = _load("api_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        now = _now()
        rid = f"wapi_req_{int(now.timestamp()*1000)}_{len(reqs)+1}"
        row = {
            "id": rid,
            "api_key_id": api_key_id_resolved,
            "tool_name": "list-api-requests",
            "state": None,
            "latitude": None,
            "longitude": None,
            "cache_key": "admin:list-api-requests",
            "served_from_cache": True,
            "response_status_code": int(status_code),
            "error_code": error_code,
            "error_message": error_message,
            "upstream_provider": None,
            "upstream_request_url": None,
            "upstream_status_code": None,
            "latency_ms": int(latency_ms),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    t0 = time.perf_counter()
    api_keys_rows = _load("api_keys.json")
    if not isinstance(api_keys_rows, list):
        api_keys_rows = []

    # Validate required
    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8")

    # Validate filters
    if tool_name is not None and tool_name not in ("get-alerts", "get-forecast"):
        return _err("VALIDATION_ERROR", "tool_name must be one of: get-alerts, get-forecast")
    if api_key_id is not None and (not isinstance(api_key_id, str) or len(api_key_id) < 1):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string")
    if state is not None:
        if not isinstance(state, str) or len(state) != 2:
            return _err("VALIDATION_ERROR", "state must be a 2-character string")
    if latitude is not None and (not isinstance(latitude, (int, float)) or latitude < -90 or latitude > 90):
        return _err("VALIDATION_ERROR", "latitude must be between -90 and 90")
    if longitude is not None and (not isinstance(longitude, (int, float)) or longitude < -180 or longitude > 180):
        return _err("VALIDATION_ERROR", "longitude must be between -180 and 180")
