        return _err("VALIDATION_ERROR", "served_from_cache must be a boolean")
    if response_status_code is not None:
        if not isinstance(response_status_code, int) or response_status_code < 100 or response_status_code > 599:
            return _err("VALIDATION_ERROR", "response_status_code must be an integer between 100 and 599")
    gte_dt = None
    lte_dt = None
    if created_at_gte is not None:
        if not isinstance(created_at_gte, str):
            return _err("VALIDATION_ERROR", "created_at_gte must be an RFC3339 date-time string")
        gte_dt = _parse_dt(created_at_gte)
        if not gte_dt:
            return _err("VALIDATION_ERROR", "created_at_gte must be an RFC3339 date-time string")
    if created_at_lte is not None:
        if not isinstance(created_at_lte, str):
            return _err("VALIDATION_ERROR", "created_at_lte must be an RFC3339 date-time string")
        lte_dt = _parse_dt(created_at_lte)
        if not lte_dt:
            return _err("VALIDATION_ERROR", "created_at_lte must be an RFC3339 date-time string")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
    if sort is None:
        sort = "created_at:desc"
    if sort not in ("created_at:asc", "created_at:desc", "latency_ms:asc", "latency_ms:desc"):
        return _err("VALIDATION_ERROR", "sort must be one of: created_at:asc, created_at:desc, latency_ms:asc, latency_ms:desc")

    auth = _find_auth_key(api_key, api_keys_rows)
    if not auth:
        return _err("UNAUTHORIZED", "API key missing or invalid")
    auth_id = auth.get("id")

    if auth.get("status") in ("suspended", "revoked"):
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, 403, error_code="KEY_INACTIVE", error_message="API key is not active; access denied.", latency_ms=latency_ms)
        return _err("UNAUTHORIZED", "API key is not active")

    # Rate limit / quota enforcement
    reqs = _load("api_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    now = _now()
    minute_start = now - datetime.timedelta(seconds=60)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

    minute_count = 0
    day_count = 0
    for r in reqs:
        if not isinstance(r, dict) or r.get("api_key_id") != auth_id:
            continue
        ts = _parse_dt(r.get("created_at"))
        if not ts:
            continue
        if ts >= minute_start:
            minute_count += 1
        if ts >= day_start:
            day_count += 1
    rpm = auth.get("requests_per_minute_limit")
    rpd = auth.get("requests_per_day_limit")
    if isinstance(rpm, int) and minute_count >= rpm or isinstance(rpd, int) and day_count >= rpd:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, 429, error_code="RATE_LIMITED", error_message="Rate limit exceeded.", latency_ms=latency_ms)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Permission model: only view own workspace
    ws = auth.get("workspace_name")
    ws_key_ids = {r.get("id") for r in api_keys_rows if isinstance(r, dict) and r.get("workspace_name") == ws}

    rows = [r for r in reqs if isinstance(r, dict) and r.get("api_key_id") in ws_key_ids]

    if tool_name is not None:
        rows = [r for r in rows if r.get("tool_name") == tool_name]
    if api_key_id is not None:
        rows = [r for r in rows if r.get("api_key_id") == api_key_id]
    if state is not None:
        rows = [r for r in rows if r.get("state") == state]
    if latitude is not None:
        rows = [r for r in rows if r.get("latitude") == latitude]
    if longitude is not None:
        rows = [r for r in rows if r.get("longitude") == longitude]
    if served_from_cache is not None:
        rows = [r for r in rows if bool(r.get("served_from_cache")) == served_from_cache]
    if response_status_code is not None:
        rows = [r for r in rows if r.get("response_status_code") == response_status_code]

    if gte_dt is not None:
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) >= gte_dt]
    if lte_dt is not None:
        rows = [r for r in rows if (_parse_dt(r.get("created_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)) <= lte_dt]

    reverse = sort.endswith(":desc")
    sort_field = sort.split(":", 1)[0]

    def _sort_key(r):
        if sort_field == "created_at":
            dt = _parse_dt(r.get("created_at"))
            return dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        if sort_field == "latency_ms":
            v = r.get("latency_ms")
            return v if isinstance(v, int) else 0
        return 0

    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor (accept either base64 offset or an id as opaque token)
    start = 0
    if cursor:
        # try offset:<int>
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if s.startswith("offset:"):
                off = int(s.split(":", 1)[1])
                if off >= 0:
                    start = off
            else:
                # treat as id
                for i, r in enumerate(rows):
                    if r.get("id") == cursor:
                        start = i + 1
                        break
        except Exception:
            # treat as id
            for i, r in enumerate(rows):
                if r.get("id") == cursor:
                    start = i + 1
                    break

    page = rows[start:start + limit]
    has_more = (start + limit) < len(rows)
    next_cursor = None
    if has_more:
        # issue offset cursor
        s = f"offset:{start + limit}".encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    latency_ms = int((time.perf_counter() - t0) * 1000)
    _log(auth_id, 200, latency_ms=latency_ms)

    return {"data": page, "meta": {"total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "sort": sort}}

