        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return _iso(_now())

    def _find_auth_key(presented, api_keys_rows):
        if not isinstance(presented, str) or len(presented) < 8:
            return None
        for r in api_keys_rows:
            if isinstance(r, dict) and r.get("id") == presented:
                return r
        return None

    def _log(api_key_id, status_code, error_code=None, error_message=None, latency_ms=0):
        reqs = _load("api_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        now = _now()
        rid = f"wapi_req_{int(now.timestamp()*1000)}_{len(reqs)+1}"
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "tool_name": "list-cache-snapshots",
            "state": None,
            "latitude": None,
            "longitude": None,
            "cache_key": "admin:list-cache-snapshots",
            "served_from_cache": True,
            "response_status_code": int(status_code),
            "error_code": error_code,
            "error_message": error_message,
            "upstream_provider": None,
            "upstream_request_url": None,
            "upstream_status_code": None,
            "latency_ms": int(latency_ms),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        reqs.append(row)
        _save("api_requests.json", reqs)

    t0 = time.perf_counter()
    api_keys_rows = _load("api_keys.json")
    if not isinstance(api_keys_rows, list):
        api_keys_rows = []

    # Validate
    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "api_key must be a string of length >= 8")
    if type not in ("alerts", "forecast"):
        return _err("VALIDATION_ERROR", "type must be one of: alerts, forecast")
    if status is not None and status not in ("fresh", "stale", "error"):
        return _err("VALIDATION_ERROR", "status must be one of: fresh, stale, error")
    if state is not None and (not isinstance(state, str) or len(state) != 2):
        return _err("VALIDATION_ERROR", "state must be a 2-character string")
    if latitude is not None and (not isinstance(latitude, (int, float)) or latitude < -90 or latitude > 90):
        return _err("VALIDATION_ERROR", "latitude must be between -90 and 90")
    if longitude is not None and (not isinstance(longitude, (int, float)) or longitude < -180 or longitude > 180):
        return _err("VALIDATION_ERROR", "longitude must be between -180 and 180")
    if geohash7 is not None and (not isinstance(geohash7, str) or len(geohash7) != 7):
        return _err("VALIDATION_ERROR", "geohash7 must be a 7-character string")
    expires_before_dt = None
    fetched_after_dt = None
    if expires_before is not None:
        if not isinstance(expires_before, str):
            return _err("VALIDATION_ERROR", "expires_before must be an RFC3339 date-time string")
        expires_before_dt = _parse_dt(expires_before)
        if not expires_before_dt:
            return _err("VALIDATION_ERROR", "expires_before must be an RFC3339 date-time string")
    if fetched_after is not None:
        if not isinstance(fetched_after, str):
            return _err("VALIDATION_ERROR", "fetched_after must be an RFC3339 date-time string")
        fetched_after_dt = _parse_dt(fetched_after)
        if not fetched_after_dt:
            return _err("VALIDATION_ERROR", "fetched_after must be an RFC3339 date-time string")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")
    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
    if sort is None:
        sort = "fetched_at:desc"
    if sort not in ("fetched_at:asc", "fetched_at:desc", "expires_at:asc", "expires_at:desc", "created_at:asc", "created_at:desc"):
        return _err("VALIDATION_ERROR", "sort must be one of: fetched_at:asc, fetched_at:desc, expires_at:asc, expires_at:desc, created_at:asc, created_at:desc")

    auth = _find_auth_key(api_key, api_keys_rows)
    if not auth:
        return _err("UNAUTHORIZED", "API key missing or invalid")
    auth_id = auth.get("id")

    if auth.get("status") in ("suspended", "revoked"):
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, 403, error_code="KEY_INACTIVE", error_message="API key is not active; access denied.", latency_ms=latency_ms)
        return _err("UNAUTHORIZED", "API key is not active")

    # Rate limit / quota enforcement
    reqs = _load("api_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    now = _now()
    minute_start = now - datetime.timedelta(seconds=60)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
    minute_count = 0
    day_count = 0
    for r in reqs:
        if not isinstance(r, dict) or r.get("api_key_id") != auth_id:
            continue
        ts = _parse_dt(r.get("created_at"))
        if not ts:
            continue
        if ts >= minute_start:
            minute_count += 1
        if ts >= day_start:
            day_count += 1
    rpm = auth.get("requests_per_minute_limit")
    rpd = auth.get("requests_per_day_limit")
    if isinstance(rpm, int) and minute_count >= rpm or isinstance(rpd, int) and day_count >= rpd:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log(auth_id, 429, error_code="RATE_LIMITED", error_message="Rate limit exceeded.", latency_ms=latency_ms)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # IMPORTANT: Relax validation per audit defect.
    # Filters that don't apply to the chosen type are ignored (not rejected).
    if type == "alerts":
        rows = _load("alert_snapshots.json")
        if not isinstance(rows, list):
            rows = []
        rows = [r for r in rows if isinstance(r, dict)]
        if status is not None:
            rows = [r for r in rows if r.get("status") == status]
        if state is not None:
            rows = [r for r in rows if r.get("state") == state]
        if expires_before_dt is not None:
            rows = [r for r in rows if (_parse_dt(r.get("expires_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)) < expires_before_dt]
        if fetched_after_dt is not None:
            rows = [r for r in rows if (_parse_dt(r.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) > fetched_after_dt]
    else:
        rows = _load("forecast_snapshots.json")
        if not isinstance(rows, list):
            rows = []
        rows = [r for r in rows if isinstance(r, dict)]
        if status is not None:
            rows = [r for r in rows if r.get("status") == status]
        if latitude is not None:
            rows = [r for r in rows if r.get("latitude") == latitude]
        if longitude is not None:
            rows = [r for r in rows if r.get("longitude") == longitude]
        if geohash7 is not None:
            rows = [r for r in rows if r.get("geohash7") == geohash7]
        if expires_before_dt is not None:
            rows = [r for r in rows if (_parse_dt(r.get("expires_at")) or datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)) < expires_before_dt]
        if fetched_after_dt is not None:
            rows = [r for r in rows if (_parse_dt(r.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) > fetched_after_dt]

    reverse = sort.endswith(":desc")
    sort_field = sort.split(":", 1)[0]

    def _sort_key(r):
        dt = _parse_dt(r.get(sort_field))
        if dt:
            return dt
        # fallbacks for missing timestamps
        if sort_field in ("fetched_at", "expires_at", "created_at"):
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor as last seen id; ignore if not found
    start = 0
    if cursor:
        for i, r in enumerate(rows):
            if r.get("id") == cursor:
                start = i + 1
                break

    page = rows[start:start + limit]
    next_cursor = page[-1]["id"] if len(page) == limit else None
    has_more = next_cursor is not None

    latency_ms = int((time.perf_counter() - t0) * 1000)
    _log(auth_id, 200, latency_ms=latency_ms)

    return {"data": page, "meta": {"total": len(rows), "limit": limit, "has_more": has_more, "next_cursor": next_cursor, "sort": sort, "type": type}}
